def longestWord(s: str) -> str:
    if not s:
        return ""
    words = s.split()
    longest = ""
    for word in words:
        if len(word) > len(longest):
            longest = word
    return longest

def main() -> None:
    test_cases = [
        "hello world python",
        "the quick brown fox jumps over the lazy dog",
        "a bb ccc dddd eeeee",
        "single",
        "",
        "  multiple   spaces   between   words  ",
        "tie first tie second",
        "a",
        "ab cd ef",
    ]
    for test in test_cases:
        result = longestWord(test)
        print(result)

if __name__ == "__main__":
    main()

