#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

typedef struct {
    char* data;
    size_t len;
} Str;

Str longestWord(Str s) {
    if (s.len == 0) {
        Str empty = {NULL, 0};
        return empty;
    }

    char* start = NULL;
    char* end = NULL;
    char* current_start = NULL;
    size_t max_len = 0;

    for (size_t i = 0; i < s.len; i++) {
        if (!isspace((unsigned char)s.data[i])) {
            if (current_start == NULL) {
                current_start = &s.data[i];
            }
        } else {
            if (current_start != NULL) {
                size_t current_len = &s.data[i] - current_start;
                if (current_len > max_len) {
                    max_len = current_len;
                    start = current_start;
                    end = &s.data[i];
                }
            }
            current_start = NULL;
        }
    }

    if (current_start != NULL) {
        size_t current_len = &s.data[s.len] - current_start;
        if (current_len > max_len) {
            max_len = current_len;
            start = current_start;
            end = &s.data[s.len];
        }
    }

    if (start == NULL) {
        Str empty = {NULL, 0};
        return empty;
    }

    size_t result_len = end - start;
    char* result_data = malloc(result_len + 1);
    if (result_data == NULL) {
        Str empty = {NULL, 0};
        return empty;
    }

    strncpy(result_data, start, result_len);
    result_data[result_len] = '\0';

    Str result = {result_data, result_len};
    return result;
}

void freeStr(Str s) {
    if (s.data != NULL) {
        free(s.data);
    }
}

int main() {
    struct {
        char* input;
        char* expected;
    } test_cases[] = {
        {"The quick brown fox jumps over the lazy dog", "quick"},
        {"Hello world from C programming", "programming"},
        {"a bb ccc dddd eeee fff gg h", "dddd"},
        {"", ""},
        {"   multiple   spaces   between   words   ", "multiple"},
        {"single", "single"},
        {"tie first second third", "first"},
        {"12345 67890 abcdef", "12345"},
        {"\t\n\r  whitespace  \t\n\r  test  \t\n\r", "whitespace"},
        {"a b c d e f g h i j k l m n o p q r s t u v w x y z", "a"}
    };

    for (size_t i = 0; i < sizeof(test_cases) / sizeof(test_cases[0]); i++) {
        Str input;
        input.data = test_cases[i].input;
        input.len = strlen(test_cases[i].input);

        Str result = longestWord(input);

        printf("Test %zu: ", i + 1);
        if (result.data == NULL) {
            printf("EMPTY\n");
        } else {
            printf("%s\n", result.data);
        }

        freeStr(result);
    }

    return 0;
}

