import java.util.*;

public class Solution {
    public static String longestWord(String s) {
        if (s.isEmpty()) {
            return "";
        }

        int num1 = 0;
        int num2 = 0;
        int start = 0;
        int maxStart = 0;
        int maxLength = 0;

        for (int i = 0; i <= s.length(); i++) {
            if (i == s.length() || s.charAt(i) == ' ') {
                num2 = i - start;
                boolean isLonger = num2 > maxLength;
                String result = switch (isLonger) {
                    case true -> {
                        maxLength = num2;
                        maxStart = start;
                        yield s.substring(maxStart, maxStart + maxLength);
                    }
                    case false -> {
                        if (maxLength == 0) {
                            yield s.substring(start, i);
                        } else {
                            yield s.substring(maxStart, maxStart + maxLength);
                        }
                    }
                };
                if (isLonger) {
                    num1 = maxStart;
                }
                start = i + 1;
            }
        }

        return s.substring(maxStart, maxStart + maxLength);
    }

    public static void main(String[] args) {
        // Test case 1: Normal sentence
        System.out.println(longestWord("The quick brown fox jumps over the lazy dog"));

        // Test case 2: Single word
        System.out.println(longestWord("Hello"));

        // Test case 3: Empty string
        System.out.println(longestWord(""));

        // Test case 4: Multiple spaces between words
        System.out.println(longestWord("One   Two    Three"));

        // Test case 5: Tie - first longest word should be returned
        System.out.println(longestWord("cat dog bat rat"));

        // Test case 6: Very long word
        System.out.println(longestWord("pneumonoultramicroscopicsilicovolcanoconiosis is a lung disease"));

        // Test case 7: Leading and trailing spaces
        System.out.println(longestWord("   leading and trailing spaces   "));
    }
}
